class TrieNode:
    def __init__(self):
        self.children = {}

class Solution:
    def minValidStrings(self, words, target):
        # Trie of all words: every non-root node is a valid prefix
        root = TrieNode()
        for word in words:
            node = root
            for c in word:
                if c not in node.children:
                    node.children[c] = TrieNode()
                node = node.children[c]

        n = len(target)
        INF = float('inf')
        # dp[i]: minimum number of valid strings needed to form target[i:]
        dp = [INF] * (n + 1)
        dp[n] = 0
        for i in range(n - 1, -1, -1):
            node = root
            best = INF
            # Walk the trie along target[i:], every node visited is a valid prefix
            for j in range(i, n):
                node = node.children.get(target[j])
                if node is None:
                    break
                if dp[j + 1] + 1 < best:
                    best = dp[j + 1] + 1
            dp[i] = best
        return -1 if dp[0] == INF else dp[0]
